<script setup lang="ts">import { ref } from 'vue'; import { useRoute } from 'vue-router'; import { createApiClient } from '../api/client'; import { createIdempotencyKey } from '../api/idempotency'; const route=useRoute(); const scores=ref([0,0,0,0]); const comment=ref(''); const anonymous=ref(false); const labels=['准时','沟通','安全','公平']; async function submit(){if(scores.value.some(s=>s<1))return; await createApiClient().submitReview({orderId:String(route.params.id),dimensions:{punctuality:scores.value[0],communication:scores.value[1],safety:scores.value[2],fairness:scores.value[3]},comment:comment.value,anonymous:anonymous.value},createIdempotencyKey())}</script>
<template><main class="page"><div class="eyebrow">同行反馈</div><h1>评价</h1><div class="detail-card"><label v-for="(l,i) in labels" :key="l">{{l}}<input v-model.number="scores[i]" type="number" min="1" max="5" /></label><label>补充说明<textarea v-model="comment" rows="3"></textarea></label><label><input v-model="anonymous" type="checkbox" /> 匿名评价</label><button class="primary-button" @click="submit">提交评价</button></div></main></template>
